<?php
/** Proof — importing the bank's CSV (spec "Proof", 1): a header, dmy dates, parentheses for debits → previewed, inserted; the same file → skipped; no reference column → hashed and said; a bad date → nothing; bank.import logged; delete the import. */
require __DIR__ . '/lib.php';
$bea = as_member(27); $vera = as_member(26);
$w = cash_world();
$may = "Date,Description,Amount,Reference\n06/05/2026,ACME TRANSFER,\"1,608.24\",REF-1\n11/05/2026,DEPOSIT,800.00,REF-2\n13/05/2026,HOSTING CO,(259.80),REF-3\n31/05/2026,MONTHLY FEE,(15.00),REF-4\n31/05/2026,INTEREST,4.10,REF-5\n";
$file = tmp_csv('SMOKE-may.csv', $may);
echo "1. The form and the preview\n";
$body = page($bea, '/cash/import?bank_account=' . $w['chk'])['body'];
ok(str_contains($body, 'id="bank-import-form"') && str_contains($body, 'id="bank-import-file"') && str_contains($body, 'id="bank-import-dateformat"') && str_contains($body, 'never stored') && preg_match('/id="bank-import-btn"[^>]*disabled/', $body) === 1, 'the form: a file field "read in memory, never stored", the date format; Import is disabled until a preview');
[$c, $html] = upload_html($bea, '/cash/import.php', ['bank_account' => $w['chk'], 'date_format' => 'dmy', 'preview' => '1'], ['file' => [$file, 'may.csv']]);
ok($c === 200 && str_contains($html, 'id="import-preview"') && str_contains($html, '5 rows in the file') && substr_count($html, '<tr><td class="text-nowrap">') === 5, 'the HTML preview shows five rows (nothing written)');
ok(str_contains($html, 'date: Date') && str_contains($html, 'amount: Amount') && str_contains($html, 'description: Description') && str_contains($html, 'reference: Reference'), 'with the detected columns by their header names');
ok(str_contains($html, 'id="bank-import-csv"') && preg_match('/id="bank-import-btn"(?![^>]*disabled)/', $html) === 1, 'the preview page holds the text for the import and enables Import (nothing stored on the server)');
ok((int) one('SELECT count(*) FROM bank_transactions WHERE bank_account_id = :b', ['b' => $w['chk']]) === 0 && (int) one('SELECT count(*) FROM bank_imports') === 0, 'a preview writes nothing');
[$c, $b] = act_upload($bea, '/cash/import.php', ['bank_account' => $w['chk'], 'date_format' => 'dmy', 'preview' => '1'], ['file' => [$file, 'may.csv']]);
ok($c === 200 && count($b['preview']['rows'] ?? []) === 5 && ($b['preview']['rows'][2]['amount'] ?? '') === '-259.80' && ($b['preview']['rows'][0]['txn_date'] ?? '') === '2026-05-06' && ($b['preview']['columns']['amount'] ?? '') === 'Amount' && ($b['preview']['hashed'] ?? -1) === 0, 'JSON: the preview rows (dmy dates, parentheses → negative) and the detected columns');
echo "2. Import\n";
$since = last_activity_id();
[$c, $b] = act_upload($bea, '/cash/import.php', ['bank_account' => $w['chk'], 'date_format' => 'dmy'], ['file' => [$file, 'may.csv']]);
$imp = (int) ($b['record_id'] ?? 0);
ok($c === 200 && $imp > 0 && ($b['rows'] ?? 0) === 5 && ($b['inserted'] ?? 0) === 5 && ($b['skipped'] ?? -1) === 0 && ($b['location'] ?? '') === '/cash/match?bank_account=' . $w['chk'] . '&notice=imported', "bank_import: 200, record_id $imp, 5 rows, 5 inserted, 0 skipped");
$lines = q('SELECT txn_date, amount, description, external_ref, status FROM bank_transactions WHERE import_id = :i ORDER BY txn_date, id', ['i' => $imp]);
ok(count($lines) === 5 && $lines[0]['txn_date'] === '2026-05-06' && $lines[0]['amount'] === '1608.24' && $lines[2]['amount'] === '-259.80' && $lines[3]['external_ref'] === 'REF-4' && array_unique(array_column($lines, 'status')) === ['unmatched'], 'five unmatched lines: the dates read dmy, the debit in parentheses is negative, the reference is the external_ref');
$l = activity('bank.import', $since)[0]; $a = json_decode((string) $l['after'], true);
ok((int) $l['bank_account_id'] === $w['chk'] && $a['import_id'] === $imp && $a['rows'] === 5 && $a['inserted'] === 5 && $a['skipped'] === 0 && $a['filename'] === 'may.csv', 'bank.import logs bank_account_id, import_id, rows, inserted, skipped, filename');
ok((string) one('SELECT row_count || \'/\' || inserted_count || \'/\' || skipped_count FROM bank_imports WHERE id = :i', ['i' => $imp]) === '5/5/0', 'the import row keeps the counts');
$since = last_activity_id();
[$c, $b] = act_upload($bea, '/cash/import.php', ['bank_account' => $w['chk'], 'date_format' => 'dmy'], ['file' => [$file, 'may.csv']]);
ok($c === 200 && ($b['inserted'] ?? -1) === 0 && ($b['skipped'] ?? -1) === 5 && (int) one('SELECT count(*) FROM bank_transactions WHERE bank_account_id = :b', ['b' => $w['chk']]) === 5, 'the same file again: 0 inserted, 5 skipped (duplicates by reference)');
ok(str_contains((string) ($b['did'] ?? ''), '5 already here'), 'and the sentence says so');
echo "3. A bank that gives no reference\n";
$noref = "Posted,Details,Debit,Credit\n2026-06-01,COFFEE,5.50,\n2026-06-01,COFFEE,5.50,\n2026-06-02,REFUND,,12.00\n";
$f2 = tmp_csv('SMOKE-noref.csv', $noref);
[$c, $html] = upload_html($bea, '/cash/import.php', ['bank_account' => $w['cash'], 'preview' => '1'], ['file' => [$f2, 'noref.csv']]);
ok($c === 200 && str_contains($html, 'id="import-preview-hashed"') && str_contains($html, 'gave no reference on 3 rows') && str_contains($html, 'debit: Debit') && str_contains($html, 'credit: Credit'), 'with no reference column the screen says so (3 rows hashed) and the debit and credit columns are detected');
$since = last_activity_id();
[$c, $b] = act_upload($bea, '/cash/import.php', ['bank_account' => $w['cash']], ['file' => [$f2, 'noref.csv']]);
$imp2 = (int) $b['record_id'];
ok($c === 200 && ($b['inserted'] ?? 0) === 3 && ($b['hashed'] ?? 0) === 3 && str_contains($b['did'], 'no reference on 3'), 'imported: 3 inserted — the two equal coffees stay two lines (a running index per file); the answer says references were hashed');
$ls = q('SELECT amount, external_ref FROM bank_transactions WHERE import_id = :i ORDER BY id', ['i' => $imp2]);
ok(str_starts_with($ls[0]['external_ref'], 'h:') && $ls[0]['external_ref'] !== $ls[1]['external_ref'] && $ls[0]['amount'] === '-5.50' && $ls[2]['amount'] === '12.00', 'debit/credit columns: money out negative, in positive; each hash differs');
[$c, $b] = act_upload($bea, '/cash/import.php', ['bank_account' => $w['cash']], ['file' => [$f2, 'noref.csv']]);
ok($c === 200 && ($b['inserted'] ?? -1) === 0 && ($b['skipped'] ?? -1) === 3, 'the same hashed file again: 0 inserted, 3 skipped');
$a = json_decode((string) activity('bank.import', $since)[0]['after'], true);
ok($a['hashed'] === 3 && $a['inserted'] === 3, 'bank.import logs the hashed count too');
echo "4. A bad file\n";
$bad = "Date,Description,Amount\n01/06/2026,OK,1.00\n31/13/2026,BAD DATE,2.00\n02/06/2026,BAD AMOUNT,abc\n";
$before = (int) one('SELECT count(*) FROM bank_transactions');
[$c, $b] = act_upload($bea, '/cash/import.php', ['bank_account' => $w['chk'], 'date_format' => 'dmy'], ['file' => [tmp_csv('SMOKE-bad.csv', $bad), 'bad.csv']]);
ok($c === 422 && str_contains(msg($b), 'Row 3: the date "31/13/2026" is not a date in the order dmy.') && str_contains(msg($b), 'Row 4: the amount "abc" is not an amount.') && str_contains(msg($b), 'Nothing was imported.'), '422 names each bad row ("Row 3: the date …", "Row 4: the amount …") and says nothing was imported');
ok((int) one('SELECT count(*) FROM bank_transactions') === $before, 'and nothing was imported');
[$c, $html] = upload_html($bea, '/cash/import.php', ['bank_account' => $w['chk'], 'date_format' => 'dmy', 'preview' => '1'], ['file' => [tmp_csv('SMOKE-bad2.csv', $bad), 'bad.csv']]);
ok($c === 200 && str_contains($html, 'id="import-preview-errors"') && str_contains($html, 'Row 3') && preg_match('/id="bank-import-btn"[^>]*disabled/', $html) === 1, 'the preview lists the errors and keeps Import disabled');
[$c, $b] = act_upload($bea, '/cash/import.php', ['bank_account' => $w['chk']], ['file' => [tmp_csv('SMOKE-empty.csv', ''), 'empty.csv']]);
ok($c === 422, 'an empty file: 422');
[$c, $b] = act_upload($bea, '/cash/import.php', ['bank_account' => $w['chk'], 'date_format' => 'ymd'], ['file' => [tmp_csv('SMOKE-nocols.csv', "Foo,Bar\n1,2\n"), 'x.csv']]);
ok($c === 422 && str_contains(msg($b), 'No date column was found'), 'a file with no date column: 422 in words');
[$c, $b] = act($bea, '/cash/import.php', ['bank_account' => $w['chk']]);
ok($c === 422 && isset(fields($b)['file']), 'no file: 422 naming the field');
[$c, $b] = act_upload($bea, '/cash/import.php', ['bank_account' => 999999], ['file' => [$file, 'may.csv']]);
ok($c === 422 && isset(fields($b)['bank_account']), 'a bank account that is not there: 422');
[$c, $b] = act_upload($vera, '/cash/import.php', ['bank_account' => $w['chk']], ['file' => [$file, 'may.csv']]);
ok($c === 403, 'a Viewer importing: 403');
[$c, $b] = act($bea, '/cash/import.php', ['bank_account' => $w['chk'], 'csv' => "Date,Description,Amount\n2026-06-09,TEXT FIELD,7.00\n", 'columns' => json_encode(['date' => 'Date', 'amount' => 'Amount', 'description' => 'Description'])]);
ok($c === 200 && ($b['inserted'] ?? 0) === 1 && ($b['hashed'] ?? 0) === 1, 'an agent may send the CSV as text with a columns map (JSON)');
echo "5. Delete an import\n";
$cashLine = (int) one('SELECT id FROM bank_transactions WHERE import_id = :i ORDER BY id LIMIT 1', ['i' => $imp2]);
[$c, $b] = act(as_member(1), '/cash/entry.php', ['bank_line' => $cashLine, 'account' => account_id('6900'), 'memo' => 'SMOKE coffee']);
ok($c === 200 && line_status($cashLine) === 'matched', 'one line of the import is matched (an entry from the line)');
$since = last_activity_id();
[$c, $b] = act($bea, '/cash/import-delete.php', ['import' => $imp2]);
ok($c === 200 && ($b['deleted'] ?? -1) === 2 && ($b['kept'] ?? -1) === 1 && (int) one('SELECT count(*) FROM bank_transactions WHERE import_id = :i', ['i' => $imp2]) === 1 && line_status($cashLine) === 'matched', 'bank_import_delete: the 2 unmatched lines are gone, the matched one stays');
ok((string) one('SELECT deleted_at IS NOT NULL FROM bank_imports WHERE id = :i', ['i' => $imp2]) === '1', 'the import row is dated deleted_at');
$l = activity('bank.import_delete', $since)[0]; $a = json_decode((string) $l['after'], true);
ok((int) $l['bank_account_id'] === $w['cash'] && $a['deleted_lines'] === 2 && $a['kept_lines'] === 1, 'bank.import_delete logs the counts');
[$c, $b] = act($bea, '/cash/import-delete.php', ['import' => $imp2]);
ok($c === 422 && str_contains(msg($b), 'already deleted'), 'deleting it twice: 422');
[$c, $b] = act($bea, '/cash/import-delete.php', ['import' => 424242]);
ok($c === 404, 'an unknown import: 404');
echo "6. A line typed by hand\n";
$since = last_activity_id();
[$c, $b] = act($bea, '/cash/line.php', ['bank_account' => $w['cash'], 'txn_date' => '2026-06-15', 'amount' => '-9.99', 'description' => 'SMOKE hand typed', 'reference' => 'H-1']);
$hand = (int) ($b['record_id'] ?? 0);
ok($c === 200 && $hand > 0 && (string) one('SELECT amount FROM bank_transactions WHERE id = :i', ['i' => $hand]) === '-9.99' && (int) one('SELECT entered_by FROM bank_transactions WHERE id = :i', ['i' => $hand]) === 27, 'bank_line_add: a typed line, entered_by the member');
ok(count(activity('bank.line_add', $since)) === 1, 'bank.line_add logged');
[$c, $b] = act($bea, '/cash/line.php', ['bank_account' => $w['cash'], 'txn_date' => 'x', 'amount' => '0', 'description' => '']);
ok($c === 422 && isset(fields($b)['txn_date'], fields($b)['amount'], fields($b)['description']), 'a bad line: 422 naming the date, the amount and the description');
finish();
